/**
 * @distilled.cloud/openbao — OpenBao HTTP API SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy models
 * in `.generated-specs` (written by `scripts/convert.ts` from the OpenAPI
 * document that `stacks/distilled-submodules/spec-repos/openbao/
 * fetch-specs.ts` generates by mounting OpenBao's own stock backends on a
 * throwaway local `-dev` server). Everything else in this folder is
 * hand-written.
 *
 * One module per mount/backend prefix — `policies`, `kv`, `pki`, `approle`,
 * `database`, `ssh`, `sys`, … — bucketed from each operation's own
 * `operationId` (see `scripts/convert.ts`'s module docs).
 *
 * @example
 * ```ts
 * import * as OpenBao from "@distilled.cloud/openbao";
 *
 * const policy = yield* OpenBao.Services.policies.policiesReadAclPolicy({
 *   name: "agent",
 * });
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export {
  OpenBaoProtocol,
  type OpenBaoOpError,
  type OpenBaoOpContext,
} from "./protocol.ts";
export * as Retry from "./retry.ts";
export * as Services from "./services/index.ts";
